def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'
    last_m, last_o = history[-1]
    if n == 1:
        return 'C' if last_o == 'C' else 'D'

    opp_d = 0
    my_d = 0
    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1

    r5 = sum(1 for i in range(max(0, n - 5), n) if history[i][1] == 'D')
    r10 = sum(1 for i in range(max(0, n - 10), n) if history[i][1] == 'D')
    r20 = sum(1 for i in range(max(0, n - 20), n) if history[i][1] == 'D')
    opp_coop = (n - opp_d) / float(n)

    forg = 0
    pun = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'D':
                pun += 1
            else:
                forg += 1

    just_f = history[-2][0] == 'D' and last_o == 'C'
    just_p = history[-2][0] == 'D' and last_o == 'D'

    exploit = (just_f and (pun == 0 or forg >= pun)) or (last_m == 'D' and last_o == 'C' and pun == 0 and forg >= 1)
    if exploit and not (r5 >= 3 and opp_coop < 0.7):
        if n >= 85:
            return 'D' if rng.random() < 0.9 else 'C'
        if pun == 0:
            return 'D' if rng.random() < 0.8 else 'C'
        return 'D' if rng.random() < 0.6 else 'C'

    if last_o == 'D' and history[-2][1] == 'D':
        return 'D'

    if n >= 5 and (r10 >= 6 or opp_d * 5 > n * 3 or (r20 >= 13 and opp_d > 0)):
        return 'D'

    if r5 >= 4 and opp_d * 2 > n:
        return 'D'

    if last_o == 'D':
        if last_m == 'D':
            if just_p and opp_coop > 0.55 and r5 <= 2 and rng.random() < 0.35:
                return 'C'
            if opp_coop > 0.55 and r5 <= 2 and forg >= pun and rng.random() < 0.35:
                return 'C'
            if opp_coop > 0.8 and r5 <= 1 and rng.random() < 0.2:
                return 'C'
            return 'D'
        if just_p and opp_coop > 0.45 and r5 <= 2 and rng.random() < 0.75:
            return 'C'
        if opp_coop > 0.75 and r5 <= 2 and forg >= pun and rng.random() < 0.6:
            return 'C'
        if opp_coop > 0.6 and r5 <= 1 and rng.random() < 0.35:
            return 'C'
        return 'D'

    if last_m == 'D':
        if pun == 0 and forg >= 1:
            return 'D' if rng.random() < 0.7 else 'C'
        if forg > pun and r10 <= 2:
            return 'D' if rng.random() < 0.45 else 'C'
        if opp_d == 0 and n >= 30:
            return 'D' if rng.random() < 0.35 else 'C'
        if my_d > opp_d + 1:
            return 'C'
        return 'C'

    if opp_d == 0:
        if n >= 85:
            return 'D' if rng.random() < 0.35 else 'C'
        if n >= 40:
            return 'D' if rng.random() < 0.18 else 'C'
        if n >= 15:
            return 'D' if rng.random() < 0.10 else 'C'
        return 'C'

    if opp_coop > 0.9 and r5 == 0 and rng.random() < 0.07:
        return 'D'
    if opp_coop > 0.7 and forg > pun and r5 <= 1 and rng.random() < 0.12:
        return 'D'
    if opp_coop > 0.55 and forg > pun and r5 <= 2 and rng.random() < 0.05:
        return 'D'

    if opp_coop < 0.25:
        return 'D' if rng.random() < 0.8 else 'C'

    if my_d > opp_d + 2 and opp_coop > 0.7:
        return 'C'

    if opp_coop > 0.5 and r5 <= 1 and rng.random() < 0.03:
        return 'D'

    return 'C'
